body:
Following is sample test which shows that schema conversion from avro does not reflect logical type from avro schema.
debugging shows that logical type is set in to props variable but is not set to logicalType instance veriable which is used by SchemaToType:165. logicalType is null while processing schema.
do we need to add code to check logical type from props?
import org.apache.avro.LogicalType;
import org.apache.avro.LogicalTypes;
import org.apache.avro.Schema;
import org.apache.iceberg.types.Type;
import org.junit.Test;
import java.io.IOException;
import static org.junit.Assert.assertEquals;

String oldAvro =
                String.join("\n",
                        " { ",
                        " \"type\": \"record\", ",
                        " \"name\": \"ExampleRecord\", ",
                        " \"fields\" : [ ",
                        " {\"name\": \"myField\", \"type\": \"long\", \"logicalType\" : \"timestamp-micros\"}, ",
                        " {\"name\": \"myField1\", \"type\": \"long\", \"logicalType\" : \"timestamp-millis\"}, ",
                        " {\"name\": \"myField2\", \"type\": \"long\", \"logicalType\" : \"time-millis\"}, ",
                        " {\"name\": \"otherField\", \"type\": \"string\"} ",
                        " ] ",
                        " }");

        Schema.Parser parser = new Schema.Parser();
        Schema avroSchema = parser.parse(oldAvro);
        org.apache.iceberg.Schema iceSchema = AvroSchemaUtil.toIceberg(avroSchema);
        assertEquals(iceSchema.findField("myField2").type(), Type.PrimitiveType.TypeID.TIME);
        System.out.println(avroSchema.toString());
